const text = ($input.first().json.content?.[0]?.text) || '{}';
const match = text.match(/\{[\s\S]*\}/);
let out = {};
try { out = JSON.parse(match ? match[0] : text); } catch (e) { throw new Error('Could not parse issue JSON'); }
const body = String(out.body || '');
const chunks = [];
for (let i = 0; i < body.length && chunks.length < 90; i += 1900) { chunks.push({ text: { content: body.slice(i, i + 1900) } }); }
return [{ json: { pageId: $('Each Planned Issue').item.json.pageId, subject: String(out.subject || '').slice(0, 200), chunks } }];

const results = $input.first().json.results || [];
return results.map(r => ({ json: {
  pageId: r.id,
  subject: r.properties?.['Subject Line']?.rich_text?.map(t => t.plain_text).join('') || (r.properties?.Issue?.title?.[0]?.plain_text || 'Donum Dei Performance'),
  body: r.properties?.Body?.rich_text?.map(t => t.plain_text).join('') || '',
  audience: r.properties?.Audience?.select?.name || 'All Subscribers'
} })).filter(i => i.json.body.length > 50);

// Build one item per recipient for the audience of each due issue.
const issue = $('Each Due Issue').item.json;
const clients = ($('Fetch Clients').first().json.results || []).map(r => r.properties?.Email?.email).filter(Boolean);
const leads = ($('Fetch Leads').first().json.results || []).map(r => r.properties?.Email?.email).filter(Boolean);
let recipients = [];
if (issue.audience === 'Clients Only') { recipients = clients; }
else if (issue.audience === 'Leads') { recipients = leads; }
else { recipients = [...new Set([...clients, ...leads])]; }
return recipients.map(email => ({ json: { email, subject: issue.subject, body: issue.body, pageId: issue.pageId } }));
